module top;

  logic clk = 1'b0;
  logic [3:0] q;
  int cyc = 0;

  always #5 clk = ~clk;

  // Generated by the VHDL library run; port names and widths follow the entity
  vhdlsub dut (.clk(clk), .q(q));

  always @(posedge clk) cyc <= cyc + 1;

  always @(negedge clk) begin
    if (cyc > 0 && q !== cyc[3:0]) begin
      $write("%%Error: q=%0d expected %0d\n", q, cyc[3:0]);
      $stop;
    end
    if (cyc == 10) begin
      $write("*-* All Finished *-*\n");
      $finish;
    end
  end

endmodule
